<?php
namespace hardness;
require_once dirname(__DIR__) . '/layout.php';
require_once dirname(dirname(__DIR__)) . '/importadores/importador_orcamento_pdf/inc/app.php';
importador_orcamento_pdf_bootstrap();
integradores_exigir_permissao(INTEGRADORES_C029_ACESSAR_PAINEL, 'Seu perfil não possui permissão para sincronizar produtos pela integração ISET.');
require_once dirname(dirname(__DIR__)) . '/bibliotecas/webservices/iset/iset.php';
if (session_id() === '') session_start();
if (empty($_SESSION['integradores_iset_produtos_csrf'])) $_SESSION['integradores_iset_produtos_csrf'] = bin2hex(random_bytes(32));
global $g;
$empresaId = isset($g['empresaAtual']) ? (int) $g['empresaAtual'] : 0;
function integradores_iset_produtos_arquivo_filtro()
{
    global $g;
    $diretorioUsuario = isset($g['pathDadosUsuario']) ? (string) $g['pathDadosUsuario'] : '';
    if ($diretorioUsuario === '' && !empty($g['pathDados']) && !empty($g['usuarioAtual'])) {
        $diretorioUsuario = rtrim((string) $g['pathDados'], '/') . '/usuarios/u_' . str_pad((string) (int) $g['usuarioAtual'], 6, '0', STR_PAD_LEFT) . '/';
    }
    if ($diretorioUsuario === '') return '';
    return rtrim($diretorioUsuario, '/') . '/gridFiltro/iset-produtos-hardness.json';
}
function integradores_iset_produtos_ler_filtros()
{
    $arquivo = integradores_iset_produtos_arquivo_filtro();
    if ($arquivo === '' || !is_file($arquivo)) return array('codigo' => '', 'descricao' => '');
    $dados = json_decode((string) @file_get_contents($arquivo), true);
    if (!is_array($dados)) return array('codigo' => '', 'descricao' => '');
    return array('codigo' => isset($dados['codigo']) ? trim((string) $dados['codigo']) : '', 'descricao' => isset($dados['descricao']) ? trim((string) $dados['descricao']) : '');
}
function integradores_iset_produtos_salvar_filtros(array $filtros)
{
    $arquivo = integradores_iset_produtos_arquivo_filtro();
    if ($arquivo === '') return;
    $diretorio = dirname($arquivo);
    if (!is_dir($diretorio) && !@mkdir($diretorio, 0777, true)) return;
    @file_put_contents($arquivo, json_encode(array('codigo' => (string) $filtros['codigo'], 'descricao' => (string) $filtros['descricao']), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), LOCK_EX);
}
function integradores_iset_produtos_limpar_filtros()
{
    $arquivo = integradores_iset_produtos_arquivo_filtro();
    if ($arquivo !== '' && is_file($arquivo)) @unlink($arquivo);
}
$carregarMais = $_SERVER['REQUEST_METHOD'] === 'GET' && isset($_GET['carregar_mais']);
$filtrosInformados = array_key_exists('codigo', $_GET) || array_key_exists('descricao', $_GET);
if (isset($_GET['limpar_filtros'])) {
    integradores_iset_produtos_limpar_filtros();
    $filtros = array('codigo' => '', 'descricao' => '');
} elseif ($filtrosInformados) {
    $filtros = array('codigo' => isset($_GET['codigo']) ? trim((string) $_GET['codigo']) : '', 'descricao' => isset($_GET['descricao']) ? trim((string) $_GET['descricao']) : '');
    if (!$carregarMais) integradores_iset_produtos_salvar_filtros($filtros);
} else {
    $filtros = integradores_iset_produtos_ler_filtros();
}
$pagina = isset($_GET['pagina']) ? (int) $_GET['pagina'] : 1;
$mensagem = ''; $tipoMensagem = ''; $resumo = null; $resumoConsulta = null; $produtosServico = new ISET_PRODUTOS();
if ($carregarMais) {
    $dados = $produtosServico->listarParaPrevia($empresaId, $filtros, $pagina, false);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($dados, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($_SESSION['integradores_iset_produtos_csrf'], isset($_POST['csrf_token']) ? (string) $_POST['csrf_token'] : '')) { $mensagem = 'Sua sessão expirou. Atualize a página e tente novamente.'; $tipoMensagem = 'erro'; }
    else {
        $acao = isset($_POST['acao']) ? (string) $_POST['acao'] : 'sincronizar';
        if ($acao === 'consultar_iset') {
            if (!empty($_POST['selecionar_todos_filtrados'])) {
                $excluir = isset($_POST['excluir_produtos']) && is_array($_POST['excluir_produtos']) ? $_POST['excluir_produtos'] : array();
                $resumoConsulta = $produtosServico->consultarTodosFiltradosNaIset($empresaId, $filtros, $excluir);
            } else {
                $selecionados = isset($_POST['produtos']) && is_array($_POST['produtos']) ? $_POST['produtos'] : array();
                $resumoConsulta = $produtosServico->consultarProdutosNaIset($empresaId, $selecionados);
            }
            $quantidade = $resumoConsulta['encontrados'] + $resumoConsulta['naoEncontrados'] + $resumoConsulta['erros'];
            $mensagem = $quantidade ? 'Consulta ISET concluída: ' . $resumoConsulta['encontrados'] . ' encontrado(s), ' . $resumoConsulta['naoEncontrados'] . ' não encontrado(s) e ' . $resumoConsulta['erros'] . ' erro(s).' : 'Selecione pelo menos um produto para consultar na ISET.';
            $tipoMensagem = $resumoConsulta['erros'] > 0 ? 'erro' : 'sucesso';
        } elseif (!empty($_POST['selecionar_todos_filtrados'])) {
            $excluir = isset($_POST['excluir_produtos']) && is_array($_POST['excluir_produtos']) ? $_POST['excluir_produtos'] : array();
            $resumo = $produtosServico->sincronizarTodosFiltrados($empresaId, $filtros, $excluir);
            $quantidade = $resumo['criados'] + $resumo['atualizados'] + $resumo['ignorados'] + $resumo['falhos'];
            $mensagem = $quantidade ? 'Sincronização concluída. Revise o resumo abaixo.' : 'Nenhum produto foi selecionado para sincronização.';
            $tipoMensagem = $resumo['falhos'] > 0 ? 'erro' : 'sucesso';
        } else {
            $selecionados = isset($_POST['produtos']) && is_array($_POST['produtos']) ? $_POST['produtos'] : array();
            $resumo = $produtosServico->sincronizarSelecionados($empresaId, $selecionados);
            $quantidade = $resumo['criados'] + $resumo['atualizados'] + $resumo['ignorados'] + $resumo['falhos'];
            $mensagem = $quantidade ? 'Sincronização concluída. Revise o resumo abaixo.' : 'Nenhum produto foi selecionado para sincronização.';
            $tipoMensagem = $resumo['falhos'] > 0 ? 'erro' : 'sucesso';
        }
    }
}
$previa = $produtosServico->listarParaPrevia($empresaId, $filtros, $pagina);
if ($mensagem === '' && !empty($previa['erro'])) { $mensagem = $previa['erro']; $tipoMensagem = 'erro'; }
function integradores_iset_produtos_valor($valor, $tipo) { if ($tipo === 'booleano') return $valor ? 'Sim' : 'Não'; if ($tipo === 'numero') return number_format((float) $valor, 2, ',', '.'); return (string) $valor; }
function integradores_iset_produtos_pendencia(array $produto) { return implode(' ', $produto['bloqueios']); }
function integradores_iset_produtos_ultima_sincronizacao(array $produto) { if (isset($produto['estadoConsulta']) && $produto['estadoConsulta'] === 'NAO_ENCONTRADO') return ''; if (empty($produto['INT005_Data_Hora_Sincronizacao'])) return ''; return integradores_formatar_data_hora(substr($produto['INT005_Data_Hora_Sincronizacao'], 0, 10), substr($produto['INT005_Data_Hora_Sincronizacao'], 11)); }
function integradores_iset_produtos_imagens($imagens) {
    if (!is_array($imagens) || !$imagens) return '<span class="iset-produtos-sem-foto">Sem foto</span>';
    $json = json_encode(array_values($imagens), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    $primeira = $imagens[0]; $miniatura = isset($primeira['miniatura']) ? $primeira['miniatura'] : $primeira['original'];
    $quantidade = count($imagens);
    return '<button class="iset-produtos-imagem-botao" type="button" data-imagens="' . integradores_h($json) . '" aria-label="Abrir galeria com ' . $quantidade . ' foto(s)"><img src="' . integradores_h($miniatura) . '" alt="Foto do produto">' . ($quantidade > 1 ? '<span>+' . ($quantidade - 1) . '</span>' : '') . '</button>';
}
function integradores_iset_produtos_valor_iset($valor, $tipo) {
    if ($tipo === 'imagens') return (is_array($valor) ? count($valor) : 0) . ' foto(s) na última consulta';
    if ($valor === null || $valor === '') return 'Não informado';
    return integradores_iset_produtos_valor($valor, $tipo);
}
function integradores_iset_produtos_celula_comparacao(array $produto, array $campo) {
    $valorHardness = isset($produto['valores'][$campo['id']]) ? $produto['valores'][$campo['id']] : null;
    $comparacao = isset($produto['comparacaoCampos'][$campo['id']]) && is_array($produto['comparacaoCampos'][$campo['id']]) ? $produto['comparacaoCampos'][$campo['id']] : array();
    $diferente = !empty($comparacao['diferente']);
    $classeComparacao = 'iset-produtos-celula-comparacao' . ($diferente ? ' iset-produtos-celula-comparacao--diferente' : '');
    if ($campo['tipo'] === 'imagens') {
        $html = integradores_iset_produtos_imagens($valorHardness);
        return '<div class="' . $classeComparacao . '">' . $html . ($diferente ? '<div class="iset-comparacao iset-comparacao-diferente"><small>ISET</small><span>' . integradores_h(integradores_iset_produtos_valor_iset(isset($comparacao['iset']) ? $comparacao['iset'] : null, 'imagens')) . '</span></div>' : '') . '</div>';
    }
    $html = '<div class="iset-comparacao-valor">' . integradores_h(integradores_iset_produtos_valor($valorHardness, $campo['tipo'])) . '</div>';
    if ($diferente) $html .= '<div class="iset-comparacao iset-comparacao-diferente"><small>ISET</small><span>' . integradores_h(integradores_iset_produtos_valor_iset(isset($comparacao['iset']) ? $comparacao['iset'] : null, $campo['tipo'])) . '</span></div>';
    return '<div class="' . $classeComparacao . '">' . $html . '</div>';
}
function integradores_iset_produtos_tem_diferenca(array $produto) { foreach (isset($produto['comparacaoCampos']) && is_array($produto['comparacaoCampos']) ? $produto['comparacaoCampos'] : array() as $comparacao) if (!empty($comparacao['diferente'])) return true; return false; }
function integradores_iset_produtos_selo_comparacao(array $produto) { return integradores_iset_produtos_tem_diferenca($produto) ? '<span class="iset-comparacao-selo">ISET</span>' : ''; }
function integradores_iset_produtos_estado_consulta(array $produto) {
    $estado = isset($produto['estadoConsulta']) ? $produto['estadoConsulta'] : 'NAO_CONSULTADO';
    if ($estado === 'NAO_ENCONTRADO') return '<small class="iset-comparacao-estado iset-comparacao-nao-encontrado">Não encontrado na ISET</small>';
    if ($estado === 'ERRO') return '<small class="iset-comparacao-estado iset-comparacao-erro">Erro ao consultar ISET</small>';
    return '';
}
