</section>
<?php if ($resumo !== null): ?><div class="iset-produtos-dialog-fundo" role="dialog" aria-modal="true" aria-labelledby="iset-produtos-sincronizacao-titulo"><section class="iset-produtos-dialog<?php echo $resumo['falhos'] > 0 ? ' iset-produtos-dialog--erro' : ''; ?>"><p class="integradores-eyebrow">Resultado</p><h3 id="iset-produtos-sincronizacao-titulo"><?php echo $resumo['falhos'] > 0 ? 'Sincronização concluída com erros' : 'Sincronização concluída'; ?></h3><p><?php echo integradores_h($mensagem); ?></p><div class="iset-produtos-resumo"><?php foreach (array('criados'=>'Criados','atualizados'=>'Atualizados','ignorados'=>'Pendências','falhos'=>'Falhos') as $campo=>$titulo): ?><div><small><?php echo $titulo; ?></small><strong><?php echo (int) $resumo[$campo]; ?></strong></div><?php endforeach; ?></div><?php if (!empty($resumo['itens'])): ?><details class="iset-produtos-aviso"><summary>Ver resultado por produto</summary><ul><?php foreach ($resumo['itens'] as $item): $resultadoItem = isset($item['resultado']) ? $item['resultado'] : 'falhos'; $rotuloItem = $resultadoItem === 'criados' ? 'Criado' : ($resultadoItem === 'atualizados' ? 'Atualizado' : ($resultadoItem === 'ignorados' ? 'Pendente' : 'Erro')); $referenciaItem = !empty($item['sku']) ? 'SKU ' . $item['sku'] : 'Produto #' . (isset($item['d009Id']) ? (int) $item['d009Id'] : ''); ?><li><?php echo integradores_h($referenciaItem); ?>: <?php echo integradores_h($rotuloItem); ?><?php if (!empty($item['mensagem'])): ?> — <?php echo integradores_h($item['mensagem']); ?><?php endif; ?></li><?php endforeach; ?></ul></details><?php endif; ?><div class="iset-produtos-dialog-acoes"><button class="iset-produtos-dialog-fechar" type="button" onclick="this.closest('.iset-produtos-dialog-fundo').remove()">Fechar</button></div></section></div><?php endif; ?>
<?php if ($resumoConsulta !== null): ?><div class="iset-produtos-dialog-fundo" role="dialog" aria-modal="true" aria-labelledby="iset-produtos-consulta-titulo"><section class="iset-produtos-dialog<?php echo $resumoConsulta['erros'] > 0 ? ' iset-produtos-dialog--erro' : ''; ?>"><p class="integradores-eyebrow">Resultado</p><h3 id="iset-produtos-consulta-titulo"><?php echo $resumoConsulta['erros'] > 0 ? 'Consulta ISET concluída com erros' : 'Consulta ISET concluída'; ?></h3><p><?php echo integradores_h($mensagem); ?></p><div class="iset-produtos-resumo"><?php foreach (array('encontrados'=>'Encontrados','naoEncontrados'=>'Não encontrados','erros'=>'Erros') as $campo=>$titulo): ?><div><small><?php echo $titulo; ?></small><strong><?php echo (int) $resumoConsulta[$campo]; ?></strong></div><?php endforeach; ?></div><?php if (!empty($resumoConsulta['resultados'])): ?><details class="iset-produtos-aviso"><summary>Ver resultado por produto</summary><ul><?php foreach ($resumoConsulta['resultados'] as $resultadoConsulta): $estado = isset($resultadoConsulta['estadoConsulta']) ? $resultadoConsulta['estadoConsulta'] : 'ERRO'; $rotulo = $estado === 'ENCONTRADO' ? 'Consultado' : ($estado === 'NAO_ENCONTRADO' ? 'Não encontrado' : 'Erro'); $referencia = !empty($resultadoConsulta['sku']) ? 'SKU ' . $resultadoConsulta['sku'] : 'Produto #' . (int) $resultadoConsulta['D009_Id']; ?><li><?php echo integradores_h($referencia); ?>: <?php echo integradores_h($rotulo); ?><?php if ($estado === 'ERRO' && !empty($resultadoConsulta['mensagem'])): ?> — <?php echo integradores_h($resultadoConsulta['mensagem']); ?><?php endif; ?></li><?php endforeach; ?></ul></details><?php endif; ?><div class="iset-produtos-dialog-acoes"><button class="iset-produtos-dialog-fechar" type="button" onclick="this.closest('.iset-produtos-dialog-fundo').remove()">Fechar</button></div></section></div><?php endif; ?>
<section class="integradores-card iset-produtos"><p class="integradores-eyebrow">Prévia para sincronização</p><h3>Produtos carregados progressivamente</h3>
<form method="post" id="iset-produtos-form"><input type="hidden" name="csrf_token" value="<?php echo integradores_h($_SESSION['integradores_iset_produtos_csrf']); ?>"><input type="hidden" name="acao" id="iset-produtos-acao" value="sincronizar"><div class="iset-produtos-tabela-wrap"><table class="iset-produtos-tabela"><thead><tr><th><input type="checkbox" id="iset-produtos-todos" aria-label="Selecionar todos os produtos filtrados"></th><?php foreach($previa['campos'] as $campo): ?><th class="<?php echo $campo['payload'] === 'name' ? 'iset-produtos-coluna--produto' : ($campo['tipo'] === 'imagens' ? 'iset-produtos-coluna--imagens' : ''); ?>"><?php echo integradores_h($campo['titulo']); ?></th><?php endforeach; ?><th>Última sincronização</th><th>Situação / pendências</th><th>Ações</th></tr></thead><tbody id="iset-produtos-corpo">
<?php foreach($previa['produtos'] as $produto): $temDiferenca=integradores_iset_produtos_tem_diferenca($produto); ?><tr class="<?php echo $produto['acao']==='BLOQUEAR'?'iset-produtos--bloqueado':''; ?>"><td class="iset-produtos-celula--selecao"><div class="iset-produtos-selecao-conteudo<?php echo $temDiferenca ? ' iset-produtos-selecao-conteudo--com-comparacao' : ''; ?>"><input class="iset-produtos-item" type="checkbox" name="produtos[]" value="<?php echo (int)$produto['D009_Id']; ?>" aria-label="Selecionar <?php echo integradores_h($produto['sku']); ?>"><?php echo integradores_iset_produtos_selo_comparacao($produto); ?></div></td><?php foreach($previa['campos'] as $campo): ?><td class="<?php echo $campo['payload'] === 'name' ? 'iset-produtos-coluna--produto' : ($campo['tipo'] === 'imagens' ? 'iset-produtos-coluna--imagens' : ''); ?>"><?php echo integradores_iset_produtos_celula_comparacao($produto, $campo); ?></td><?php endforeach; ?><td><?php echo integradores_h(integradores_iset_produtos_ultima_sincronizacao($produto)); ?></td><td class="iset-produtos-pendencia"><?php echo $produto['bloqueios'] ? integradores_h(integradores_iset_produtos_pendencia($produto)) : 'Pronto'; ?></td><td><?php if($produto['acao'] !== ''): ?><span class="iset-produtos-status iset-produtos-status--<?php echo integradores_h($produto['acao']); ?>"><?php echo integradores_h($produto['acao'] === 'CRIAR' ? 'Criar' : ($produto['acao'] === 'ATUALIZAR' ? 'Atualizar' : 'Bloqueado')); ?></span><?php endif; ?><?php echo integradores_iset_produtos_estado_consulta($produto); ?></td></tr><?php endforeach; ?><?php if(!$previa['produtos']): ?><tr><td colspan="<?php echo count($previa['campos'])+4; ?>">Nenhum produto encontrado.</td></tr><?php endif; ?></tbody></table></div><div class="iset-produtos-aviso">Produtos bloqueados podem ser consultados na ISET; as validações continuam impedindo uma nova criação indevida.</div></form>
<div class="iset-produtos-carregar" id="iset-produtos-carregar"<?php echo empty($previa['paginacao']['temMais']) ? ' hidden' : ''; ?>><button class="integradores-button integradores-button--secundario" type="button" id="iset-produtos-carregar-botao">Carregar mais produtos</button><span id="iset-produtos-carregar-status" aria-live="polite"></span></div>
</section>
<dialog class="iset-produtos-galeria" id="iset-produtos-galeria" aria-label="Galeria de fotos do produto"><div class="iset-produtos-galeria__conteudo"><button class="integradores-button integradores-button--secundario iset-produtos-galeria__fechar" type="button" aria-label="Fechar galeria">Fechar</button><img class="iset-produtos-galeria__imagem" id="iset-produtos-galeria-imagem" alt="Foto ampliada do produto"><div class="iset-produtos-galeria__rodape"><button class="integradores-button integradores-button--secundario" id="iset-produtos-galeria-anterior" type="button">Anterior</button><strong id="iset-produtos-galeria-contador" aria-live="polite">1 de 1</strong><button class="integradores-button integradores-button--secundario" id="iset-produtos-galeria-proxima" type="button">Próxima</button></div><div class="iset-produtos-galeria__miniaturas" id="iset-produtos-galeria-miniaturas" aria-label="Miniaturas da galeria"></div></div></dialog>
<script>
(function(){
    var todos=document.getElementById('iset-produtos-todos'), corpo=document.getElementById('iset-produtos-corpo'), formulario=document.getElementById('iset-produtos-form'), campoAcao=document.getElementById('iset-produtos-acao'), carregar=document.getElementById('iset-produtos-carregar'), botao=document.getElementById('iset-produtos-carregar-botao'), status=document.getElementById('iset-produtos-carregar-status'), totalSelecionados=document.getElementById('iset-produtos-selecionados'), botaoConsultar=document.getElementById('iset-produtos-consultar'), botaoSincronizar=document.getElementById('iset-produtos-sincronizar'), statusAcao=document.getElementById('iset-produtos-acao-status'), galeria=document.getElementById('iset-produtos-galeria'), imagemGaleria=document.getElementById('iset-produtos-galeria-imagem'), contadorGaleria=document.getElementById('iset-produtos-galeria-contador'), miniaturasGaleria=document.getElementById('iset-produtos-galeria-miniaturas'), anteriorGaleria=document.getElementById('iset-produtos-galeria-anterior'), proximaGaleria=document.getElementById('iset-produtos-galeria-proxima'), chaveSelecao='iset-produtos-selecao-<?php echo (int) $empresaId; ?>-'+JSON.stringify(<?php echo json_encode($filtros, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>), estado={todos:false,ids:{}}, imagensGaleria=[], indiceGaleria=0, acaoSubmetida='sincronizar';
    var campos=<?php echo json_encode($previa['campos'], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>, filtros=<?php echo json_encode($filtros, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>, totalFiltrados=<?php echo (int) $previa['totalFiltrados']; ?>, pagina=1, temMais=<?php echo !empty($previa['paginacao']['temMais']) ? 'true' : 'false'; ?>, carregando=false;
    try{var salvo=JSON.parse(window.sessionStorage.getItem(chaveSelecao)||'null');if(salvo&&salvo.ids)estado={todos:!!salvo.todos,ids:salvo.ids};else if(salvo&&typeof salvo==='object')estado={todos:false,ids:salvo};}catch(erro){}
    function salvarSelecionados(){try{window.sessionStorage.setItem(chaveSelecao,JSON.stringify(estado));}catch(erro){}}
    function estaSelecionado(id){return estado.todos?!estado.ids[String(id)]:!!estado.ids[String(id)];}
    function registrarSelecao(item){var id=String(item.value);if(estado.todos){if(item.checked)delete estado.ids[id];else estado.ids[id]=true;}else if(item.checked)estado.ids[id]=true;else delete estado.ids[id];salvarSelecionados();}
    function atualizarSelecionados(){var quantidade=estado.todos?Math.max(0,totalFiltrados-Object.keys(estado.ids).length):Object.keys(estado.ids).length;if(totalSelecionados)totalSelecionados.textContent=quantidade;if(todos){todos.checked=estado.todos;todos.indeterminate=estado.todos&&Object.keys(estado.ids).length>0;}}
    function aplicarSelecao(escopo){(escopo||document).querySelectorAll('.iset-produtos-item').forEach(function(item){item.checked=estaSelecionado(item.value);});}
    if(todos)todos.addEventListener('change',function(){estado={todos:todos.checked,ids:{}};salvarSelecionados();aplicarSelecao();atualizarSelecionados();});
    if(corpo)corpo.addEventListener('change',function(evento){if(evento.target.classList.contains('iset-produtos-item')){registrarSelecao(evento.target);atualizarSelecionados();}});
    function valor(valor,tipo){if(tipo==='booleano')return valor?'Sim':'Não';if(tipo==='numero')return Number(valor).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});return valor===null||typeof valor==='undefined'?'':String(valor);}
    function celula(texto,classe){var celula=document.createElement('td');if(classe)celula.className=classe;celula.textContent=texto;return celula;}
    function celulaImagens(imagens){var coluna=document.createElement('td');coluna.className='iset-produtos-coluna--imagens';if(!Array.isArray(imagens)||!imagens.length){var semFoto=document.createElement('span');semFoto.className='iset-produtos-sem-foto';semFoto.textContent='Sem foto';coluna.appendChild(semFoto);return coluna;}var botaoImagem=document.createElement('button'),imagem=document.createElement('img');botaoImagem.type='button';botaoImagem.className='iset-produtos-imagem-botao';botaoImagem.dataset.imagens=JSON.stringify(imagens);botaoImagem.setAttribute('aria-label','Abrir galeria com '+imagens.length+' foto(s)');imagem.src=imagens[0].miniatura||imagens[0].original;imagem.alt='Foto do produto';botaoImagem.appendChild(imagem);if(imagens.length>1){var selo=document.createElement('span');selo.textContent='+'+(imagens.length-1);botaoImagem.appendChild(selo);}coluna.appendChild(botaoImagem);return coluna;}
    function valorIset(valorRemoto,tipo){if(valorRemoto===null||typeof valorRemoto==='undefined'||valorRemoto==='')return 'Não informado';return valor(valorRemoto,tipo);}
    function celulaComparacao(produto,campo){var comparacao=produto.comparacaoCampos&&produto.comparacaoCampos[campo.id]?produto.comparacaoCampos[campo.id]:null,diferente=!!(comparacao&&comparacao.diferente),classe=campo.payload==='name'?'iset-produtos-coluna--produto':'';if(campo.tipo==='imagens'){var coluna=celulaImagens(produto.valores[campo.id]),conteudo=document.createElement('div');conteudo.className='iset-produtos-celula-comparacao'+(diferente?' iset-produtos-celula-comparacao--diferente':'');while(coluna.firstChild)conteudo.appendChild(coluna.firstChild);if(diferente){var linhaIset=document.createElement('div'),rotuloIset=document.createElement('small'),valorIsetImagem=document.createElement('span');linhaIset.className='iset-comparacao iset-comparacao-diferente';rotuloIset.textContent='ISET';valorIsetImagem.textContent=(Array.isArray(comparacao.iset)?comparacao.iset.length:0)+' foto(s) na última consulta';linhaIset.appendChild(rotuloIset);linhaIset.appendChild(valorIsetImagem);conteudo.appendChild(linhaIset);}coluna.appendChild(conteudo);return coluna;}var coluna=celula('',classe),conteudo=document.createElement('div'),valorHardness=document.createElement('div');conteudo.className='iset-produtos-celula-comparacao'+(diferente?' iset-produtos-celula-comparacao--diferente':'');valorHardness.className='iset-comparacao-valor';valorHardness.textContent=valor(produto.valores[campo.id],campo.tipo);conteudo.appendChild(valorHardness);if(diferente){var linhaRemota=document.createElement('div'),rotulo=document.createElement('small'),valorRemoto=document.createElement('span');linhaRemota.className='iset-comparacao iset-comparacao-diferente';rotulo.textContent='ISET';valorRemoto.textContent=valorIset(comparacao.iset,campo.tipo);linhaRemota.appendChild(rotulo);linhaRemota.appendChild(valorRemoto);conteudo.appendChild(linhaRemota);}coluna.appendChild(conteudo);return coluna;}
    function estadoConsulta(produto,acoes){if(produto.estadoConsulta==='NAO_ENCONTRADO'||produto.estadoConsulta==='ERRO'){var estado=document.createElement('small');estado.className='iset-comparacao-estado '+(produto.estadoConsulta==='NAO_ENCONTRADO'?'iset-comparacao-nao-encontrado':'iset-comparacao-erro');estado.textContent=produto.estadoConsulta==='NAO_ENCONTRADO'?'Não encontrado na ISET':'Erro ao consultar ISET';acoes.appendChild(estado);}}
    function possuiDiferenca(produto){var camposComparacao=produto.comparacaoCampos||{};return Object.keys(camposComparacao).some(function(chave){return !!camposComparacao[chave].diferente;});}
    function ultimaSincronizacao(produto){var data=produto.INT005_Data_Hora_Sincronizacao||'';if(produto.estadoConsulta==='NAO_ENCONTRADO'||!data)return '';var partes=String(data).split(' '),dia=partes[0]?partes[0].split('-'):[];return dia.length===3?dia[2]+'/'+dia[1]+'/'+dia[0]+(partes[1]?' '+partes[1]:''):String(data);}
    function inserir(produto){var linha=document.createElement('tr'),celulaSelecao=document.createElement('td'),conteudoSelecao=document.createElement('div'),temDiferenca=possuiDiferenca(produto),checkbox=document.createElement('input');celulaSelecao.className='iset-produtos-celula--selecao';conteudoSelecao.className='iset-produtos-selecao-conteudo'+(temDiferenca?' iset-produtos-selecao-conteudo--com-comparacao':'');if(produto.acao==='BLOQUEAR')linha.className='iset-produtos--bloqueado';checkbox.type='checkbox';checkbox.className='iset-produtos-item';checkbox.name='produtos[]';checkbox.value=produto.D009_Id;checkbox.checked=estaSelecionado(produto.D009_Id);checkbox.setAttribute('aria-label','Selecionar '+produto.sku);conteudoSelecao.appendChild(checkbox);if(temDiferenca){var selo=document.createElement('span');selo.className='iset-comparacao-selo';selo.textContent='ISET';conteudoSelecao.appendChild(selo);}celulaSelecao.appendChild(conteudoSelecao);linha.appendChild(celulaSelecao);campos.forEach(function(campo){linha.appendChild(celulaComparacao(produto,campo));});linha.appendChild(celula(ultimaSincronizacao(produto)));linha.appendChild(celula(produto.bloqueios&&produto.bloqueios.length?produto.bloqueios.join(' '):'Pronto','iset-produtos-pendencia'));var acoes=document.createElement('td');if(produto.acao){var etiqueta=document.createElement('span');etiqueta.className='iset-produtos-status iset-produtos-status--'+produto.acao;etiqueta.textContent=produto.acao==='CRIAR'?'Criar':(produto.acao==='ATUALIZAR'?'Atualizar':'Bloqueado');acoes.appendChild(etiqueta);}estadoConsulta(produto,acoes);linha.appendChild(acoes);corpo.appendChild(linha);}
    function renderizarGaleria(){if(!imagensGaleria.length)return;var foto=imagensGaleria[indiceGaleria];imagemGaleria.src=foto.original;contadorGaleria.textContent=(indiceGaleria+1)+' de '+imagensGaleria.length;anteriorGaleria.disabled=indiceGaleria===0;proximaGaleria.disabled=indiceGaleria===imagensGaleria.length-1;miniaturasGaleria.textContent='';imagensGaleria.forEach(function(item,indice){var botaoMiniatura=document.createElement('button'),imagemMiniatura=document.createElement('img');botaoMiniatura.type='button';botaoMiniatura.className=indice===indiceGaleria?'active':'';botaoMiniatura.setAttribute('aria-label','Exibir foto '+(indice+1));imagemMiniatura.src=item.miniatura||item.original;imagemMiniatura.alt='Miniatura '+(indice+1);botaoMiniatura.appendChild(imagemMiniatura);botaoMiniatura.addEventListener('click',function(){indiceGaleria=indice;renderizarGaleria();});miniaturasGaleria.appendChild(botaoMiniatura);});}
    function abrirGaleria(imagens){if(!galeria||!Array.isArray(imagens)||!imagens.length)return;imagensGaleria=imagens;indiceGaleria=0;renderizarGaleria();if(!galeria.open)galeria.showModal();}
    if(corpo)corpo.addEventListener('click',function(evento){var alvo=evento.target;while(alvo&&alvo!==corpo&&!alvo.classList.contains('iset-produtos-imagem-botao'))alvo=alvo.parentNode;if(!alvo||alvo===corpo)return;try{abrirGaleria(JSON.parse(alvo.dataset.imagens||'[]'));}catch(erro){}});
    if(anteriorGaleria)anteriorGaleria.addEventListener('click',function(){if(indiceGaleria>0){indiceGaleria--;renderizarGaleria();}});
    if(proximaGaleria)proximaGaleria.addEventListener('click',function(){if(indiceGaleria<imagensGaleria.length-1){indiceGaleria++;renderizarGaleria();}});
    if(galeria){var fecharGaleria=galeria.querySelector('.iset-produtos-galeria__fechar');if(fecharGaleria)fecharGaleria.addEventListener('click',function(){galeria.close();});galeria.addEventListener('cancel',function(){imagensGaleria=[];});galeria.addEventListener('click',function(evento){if(evento.target===galeria)galeria.close();});}
    function buscarMais(){if(!temMais||carregando)return;carregando=true;botao.disabled=true;status.textContent='Carregando...';var parametros=new URLSearchParams({carregar_mais:'1',pagina:String(pagina+1),codigo:filtros.codigo||'',descricao:filtros.descricao||''});fetch(window.location.pathname+'?'+parametros.toString(),{credentials:'same-origin'}).then(function(resposta){if(!resposta.ok)throw new Error();return resposta.json();}).then(function(dados){if(dados.erro)throw new Error(dados.erro);dados.produtos.forEach(inserir);pagina++;temMais=!!(dados.paginacao&&dados.paginacao.temMais);carregar.hidden=!temMais;status.textContent='';carregando=false;botao.disabled=false;}).catch(function(){status.textContent='Não foi possível carregar mais produtos.';carregando=false;botao.disabled=false;});}
    if(botao)botao.addEventListener('click',buscarMais);
    if(carregar&&window.IntersectionObserver){new IntersectionObserver(function(entradas){entradas.forEach(function(entrada){if(entrada.isIntersecting)buscarMais();});},{rootMargin:'240px'}).observe(carregar);}
    if(botaoConsultar)botaoConsultar.addEventListener('click',function(){acaoSubmetida='consultar_iset';});
    if(botaoSincronizar)botaoSincronizar.addEventListener('click',function(){acaoSubmetida='sincronizar';});
    if(formulario)formulario.addEventListener('submit',function(evento){var acao=evento.submitter&&evento.submitter.value?evento.submitter.value:acaoSubmetida;if(campoAcao)campoAcao.value=acao;formulario.querySelectorAll('[data-iset-selecao]').forEach(function(campo){campo.remove();});function oculto(nome,valor){var campo=document.createElement('input');campo.type='hidden';campo.name=nome;campo.value=valor;campo.setAttribute('data-iset-selecao','1');formulario.appendChild(campo);}var quantidade=estado.todos?Math.max(0,totalFiltrados-Object.keys(estado.ids).length):Object.keys(estado.ids).length;if(acao==='consultar_iset'&&quantidade===0){evento.preventDefault();if(statusAcao)statusAcao.textContent='Selecione pelo menos um produto para consultar na ISET.';return;}if(estado.todos){oculto('selecionar_todos_filtrados','S');Object.keys(estado.ids).forEach(function(id){oculto('excluir_produtos[]',id);});}else{var presentes={};document.querySelectorAll('.iset-produtos-item:checked').forEach(function(item){presentes[String(item.value)]=true;});Object.keys(estado.ids).forEach(function(id){if(!presentes[id])oculto('produtos[]',id);});}if(acao==='consultar_iset'){if(statusAcao)statusAcao.textContent='Consultando produtos na ISET...';if(botaoConsultar){botaoConsultar.disabled=true;botaoConsultar.textContent='Consultando...';}if(botaoSincronizar)botaoSincronizar.disabled=true;}});
    aplicarSelecao();atualizarSelecionados();
}());
</script>
<?php integradores_footer(); ?>
